/** request ids slower than ms */
function slowRequests(lines, ms) {
  // Write your solution here
  const ids = [];
  for (const line of lines) {
    const m = /"durationMs":(\d{4,})/.exec(line);
    if (m) ids.push(JSON.parse(line).requestId);
  }
  return ids;
}

